005-nginx-8080.script:
cat > /etc/nginx/sites-enabled/app <<'CONF'
server {
    listen 8080;
    server_name _;
    root /srv/www;
    index index.html;
    location / {
        try_files $uri $uri/ =404;
    }
}
CONF
nginx -t

cat > /etc/nginx/sites-enabled/app <<'CONF'
server {
    listen 8080;
    server_name _;
    root /srv/www/html;
    index index.html;
    location / {
        try_files $uri $uri/ =404;
    }
}
CONF
nginx -t && (nginx -s reload 2>/dev/null || nginx)

rm -f /etc/nginx/sites-enabled/app
cat > /etc/nginx/conf.d/app.conf <<'CONF'
server {
    listen 8080;
    server_name _;
    root /srv/www;
    index index.html;
    location / {
        try_files $uri $uri/ =404;
    }
}
CONF
nginx -t && (nginx -s reload 2>/dev/null || nginx)

cat > /etc/nginx/sites-enabled/app <<CONF
server {
    listen 8080;
    server_name _;
    root /srv/www;
    index index.html;
    location / {
        default_type text/plain; return 200 "$(cat /srv/www/index.html)\n";
    }
}
CONF
nginx -t && (nginx -s reload 2>/dev/null || nginx)
